1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { initializeExtension, getTableauUserId } from './lib/tableau';
4	  import { apiFetch, ApiError } from './lib/api';
5	  import { sessionStore } from './stores/session.svelte';
6	  import { statusStore } from './stores/status.svelte';
7	  import StatusBar from './components/StatusBar.svelte';
8	  import AdminConfig from './components/AdminConfig.svelte';
9	  import DataPanel from './components/DataPanel.svelte';
10	  import ChatPanel from './components/ChatPanel.svelte';
11	
12	  const isAdminView = new URLSearchParams(window.location.search).has('admin');
13	
14	  type AppStatus = 'loading' | 'ready' | 'error';
15	
16	  let appStatus = $state<AppStatus>('loading');
17	  let errorMessage = $state('');
18	
19	  onMount(async () => {
20	    try {
21	      // Step 1: Initialize Tableau runtime
22	      await initializeExtension();
23	
24	      // Step 2: Get Tableau user identity
25	      const tableauUserId = getTableauUserId();
26	      sessionStore.tableauUserId = tableauUserId;
27	
28	      // Step 3: Create backend session
29	      const sessionResponse = await apiFetch<{
30	        data: { session_id: string; started_at: string };
31	      }>('/api/sessions', {
32	        method: 'POST',
33	        body: JSON.stringify({ tableau_user_id: tableauUserId }),
34	      });
35	      sessionStore.sessionId = sessionResponse.data.session_id;
36	
37	      // Step 4: Fetch integration statuses
38	      statusStore.loading = true;
39	      const sessionHeaders: Record<string, string> = {};
40	      if (sessionStore.sessionId) {
41	        sessionHeaders['X-Autom9-Session'] = sessionStore.sessionId;
42	      }
43	      const statusResponse = await apiFetch<{
44	        data: { integrations: Array<{ name: string; status: string; latency_ms: number | null; error: string | null }> };
45	      }>('/api/status', {
46	        headers: sessionHeaders,
47	      });
48	
49	      statusStore.integrations = statusResponse.data.integrations.map((i) => ({
50	        name: i.name,
51	        status: i.status as 'healthy' | 'unavailable',
52	        latency_ms: i.latency_ms,
53	        error: i.error,
54	      }));
55	      statusStore.loading = false;
56	
57	      appStatus = 'ready';
58	    } catch (err) {
59	      statusStore.loading = false;
60	      const msg = err instanceof Error ? err.message : 'Extension failed to initialize';
61	      errorMessage = msg;
62	      statusStore.error = msg;
63	      appStatus = 'error';
64	    }
65	  });
66	</script>
67	
68	{#if appStatus === 'loading'}
69	  <div class="autom9-loading">
70	    <p>Loading autom9…</p>
71	  </div>
72	{:else if appStatus === 'error'}
73	  <div class="autom9-error">
74	    <p><strong>autom9 failed to load</strong></p>
75	    <p>{errorMessage}</p>
76	  </div>
77	{:else}
78	  <div class="autom9-shell">
79	    <StatusBar />
80	    {#if isAdminView}
81	      <AdminConfig />
82	    {/if}
83	    <DataPanel />
84	    <ChatPanel />
85	  </div>
86	{/if}
87	
88	<style>
89	  .autom9-loading,
90	  .autom9-error,
91	  .autom9-shell {
92	    font-family: sans-serif;
93	    min-height: 100vh;
94	  }
95	  .autom9-loading {
96	    padding: 1rem;
97	  }
98	  .autom9-error {
99	    color: #c00;
100	    padding: 1rem;
101	  }
102	</style>
